-- 0002: identity & tenancy
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, email text, full_name text, phone text, avatar_url text, locale text not null default 'en', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
create table public.user_roles (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, role public.platform_role not null, created_at timestamptz not null default now(), unique(user_id, role));
create table public.businesses (id uuid primary key default gen_random_uuid(), slug text not null unique, name text not null, description text, logo_url text, cover_url text, industry text, email text, phone text, address text, city text, country text not null default 'BD', timezone text not null default 'Asia/Dhaka', currency text not null default 'BDT', status public.business_status not null default 'pending', is_published boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
create index businesses_slug_idx on public.businesses(slug); create index businesses_status_idx on public.businesses(status);
create table public.business_members (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, role public.business_role not null, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, unique(business_id, user_id));
create index business_members_biz_idx on public.business_members(business_id); create index business_members_user_idx on public.business_members(user_id);
create table public.business_invitations (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, email text not null, role public.business_role not null default 'staff', token_hash text not null, expires_at timestamptz not null, accepted_at timestamptz, created_at timestamptz not null default now());
create index business_invitations_biz_idx on public.business_invitations(business_id);
create table public.business_settings (business_id uuid primary key references public.businesses(id) on delete cascade, brand_color text default '#4f46e5', min_advance_minutes int not null default 60, max_advance_days int not null default 60, cancellation_deadline_hours int not null default 2, slot_interval_minutes int not null default 30, auto_confirm boolean not null default false, settings jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.business_domains (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, domain text not null unique, is_verified boolean not null default false, verification_token text, created_at timestamptz not null default now());
create index business_domains_biz_idx on public.business_domains(business_id);
create table public.business_hours (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, day_of_week int not null check (day_of_week between 0 and 6), open_time time, close_time time, is_closed boolean not null default false, created_at timestamptz not null default now(), unique(business_id, day_of_week));
create index business_hours_biz_idx on public.business_hours(business_id);
create table public.business_holidays (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, holiday_date date not null, name text not null, created_at timestamptz not null default now(), unique(business_id, holiday_date));
create index business_holidays_biz_idx on public.business_holidays(business_id, holiday_date);
create trigger profiles_updated before update on public.profiles for each row execute function public.set_updated_at();
create trigger businesses_updated before update on public.businesses for each row execute function public.set_updated_at();
create trigger business_members_updated before update on public.business_members for each row execute function public.set_updated_at();
create trigger business_settings_updated before update on public.business_settings for each row execute function public.set_updated_at();
